WITH CustomerStats AS (SELECT customer_id, AVG(monthly_fee) AS avg_monthly_fee, ROUND((100 * SUM(CASE WHEN plan = 'standard' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_standard FROM subscriptions GROUP BY customer_id) SELECT c.id, c.city, c.signup_date, C.avg_monthly_fee, C.pct_standard FROM customers c INNER JOIN CustomerStats C ON c.id = C.customer_id ORDER BY city DESC, id ASC LIMIT 10;
